import {useEffect} from 'react'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import type {EnterpriseCloudSummaryData} from '../types/enterprise-cloud-summary-data'
import {EnterpriseCloudUsageSummary} from '@github-ui/licensing-common/components/EnterpriseCloudUsageSummary'
import {EnterpriseCloudPaymentSummary} from '@github-ui/licensing-common/components/EnterpriseCloudPaymentSummary'
import {SummarySection} from '@github-ui/licensing-common/components/SummarySection'

export function SummarySectionContainer({
  initialSummaryData,
  refreshToken,
}: {
  initialSummaryData: EnterpriseCloudSummaryData
  refreshToken: number // increment to trigger refetching of summary data
}) {
  const {basePath} = useNavigation()
  const {
    data: summaryData,
    isError,
    isFetching,
    refetch,
  } = useQuery<EnterpriseCloudSummaryData>({
    queryKey: ['licensing', basePath, 'enterprise-cloud-summary'],
    queryFn: async () => {
      const url = new URL(`${basePath}/licensing/ghec/summary`, window.location.origin)
      const resp = await verifiedFetchJSON(url.toString())
      if (!resp.ok) {
        throw new Error(`Failed to fetch summary data: ${resp.status} ${resp.statusText}`)
      }
      return await resp.json()
    },
    initialData: initialSummaryData,
    refetchOnMount: false,
    refetchOnWindowFocus: true,
  })
  const isTrial = !!summaryData.trialInfo

  useEffect(() => {
    // only refetch if refreshToken has changed (i.e., not the initial render)
    if (refreshToken > 0) {
      void refetch()
    }
  }, [refetch, refreshToken])

  return (
    <SummarySection
      isError={isError}
      isLoading={isFetching}
      summaries={[
        <EnterpriseCloudUsageSummary
          key="usage-summary"
          canViewMembers={summaryData.canViewMembers}
          headingAs="h2"
          isTrial={isTrial}
          isVolumeLicensed={summaryData.isVolumeLicensed}
          enterpriseLicensesConsumed={summaryData.enterpriseLicensesConsumed}
          enterpriseLicensesPurchased={summaryData.enterpriseLicensesPurchased}
          vssLicensesConsumed={summaryData.vssLicensesConsumed}
          vssLicensesPurchasedWithOverage={summaryData.vssLicensesPurchasedWithOverage}
          isVssEnabled={summaryData.isVssEnabled}
        />,
        <EnterpriseCloudPaymentSummary
          key="payment-summary"
          billingTermEndDate={summaryData.billingTermEndDate}
          currentPayment={summaryData.currentPayment}
          enterpriseLicensesBillable={summaryData.enterpriseLicensesBillable}
          headingAs="h2"
          isMonthly={summaryData.isMonthly}
          isTrial={isTrial}
          isVolumeLicensed={summaryData.isVolumeLicensed}
          isVssEnabled={summaryData.isVssEnabled}
          unitCost={summaryData.unitCost}
        />,
      ]}
    />
  )
}
