import {useRef, useCallback, useState} from 'react'
import {useDebounce} from '@github-ui/use-debounce'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {SubscriptionIdentifier} from '../types/subscription-identifier'

export function useMatchCandidateSearch(slug: string, currentMatch?: SubscriptionIdentifier) {
  const abortControllerRef = useRef<AbortController | null>(null)
  const [loading, setLoading] = useState(false)
  const [results, setResults] = useState<SubscriptionIdentifier[]>([])

  const fetchNow = useCallback(
    async (query: string) => {
      if (!query) {
        setResults([])
        return
      }

      abortControllerRef.current?.abort()
      const controller = new AbortController()
      abortControllerRef.current = controller

      setLoading(true)

      try {
        const url = `/enterprises/${encodeURIComponent(
          slug,
        )}/licensing/bundled_license_assignments/search?email_or_upn=${encodeURIComponent(query)}`
        const resp = await verifiedFetchJSON(url, {signal: controller.signal})
        const data = await resp.json()

        const q = query.toLowerCase()
        const fetchedItems = Array.isArray(data)
          ? data
              .map(item => {
                const email = item.email || ''
                const identity = item.identity || ''
                if (email.toLowerCase().startsWith(q) || identity.toLowerCase().startsWith(q)) {
                  return {
                    id: item.id,
                    email,
                    identity,
                  }
                }
                return null
              })
              .filter((item): item is SubscriptionIdentifier => !!item)
          : []

        const filteredCurrentMatch =
          currentMatch &&
          (currentMatch.email.toLowerCase().startsWith(q) || currentMatch.identity.toLowerCase().startsWith(q))
            ? [currentMatch]
            : []

        setResults([...filteredCurrentMatch, ...fetchedItems])
      } catch (err) {
        if ((err as Error).name === 'AbortError') {
          // Request was aborted, no need to log an error
          return
        }
        // eslint-disable-next-line no-console
        console.error('useMatchCandidateSearch error:', err)
        setResults([])
      } finally {
        setLoading(false)
      }
    },
    [slug, currentMatch],
  )

  const debouncedFetch = useDebounce(fetchNow, 400)

  const search = useCallback(
    (query: string) => {
      debouncedFetch(query)
    },
    [debouncedFetch],
  )

  return {
    search,
    loading,
    results,
    abort: () => {
      abortControllerRef.current?.abort()
      abortControllerRef.current = null
    },
  }
}
