export type ChangeType = 'added' | 'removed'

export type User = {
  login: string
  avatarUrl: string
}

export type DetailedChange = {
  id: string
  user: {
    login: string
    avatarUrl: string
  }
  performedBy: {
    login: string
    avatarUrl: string
  }
  performedAt: string
}

export type LicenseChange = {
  id: string
  changeType: ChangeType
  licenseCount: number
  effectiveDate: string
  user?: User
  additionalUsers?: User[]
  detailedEvents?: DetailedChange[]
}

export const CHANGE_TYPE_LABELS: Record<ChangeType, string> = {
  added: 'Added',
  removed: 'Removed',
} as const

export const CHANGE_TYPE_COLORS: Record<ChangeType, string> = {
  added: 'success',
  removed: 'danger',
} as const
